#include <string>
#include <vector>
#include <cmath>

class Solution {
public:
    bool checkAlmostEquivalent(std::string word1, std::string word2) {
        std::vector<int> diff(26, 0);
        for (char c : word1) diff[c - 'a']++;
        for (char c : word2) diff[c - 'a']--;
        for (int d : diff) {
            if (std::abs(d) > 3) return false;
        }
        return true;
    }
};

class Solution {
    public boolean checkAlmostEquivalent(String word1, String word2) {
        int[] diff = new int[26];
        for (int i = 0; i < word1.length(); i++) {
            diff[word1.charAt(i) - 'a']++;
            diff[word2.charAt(i) - 'a']--;
        }
        for (int d : diff) {
            if (Math.abs(d) > 3) return false;
        }
        return true;
    }
}

